package com.elogistic.backend.orders.internal.infrastructure;

import com.elogistic.backend.orders.api.*;
import com.elogistic.backend.orders.api.MerchantFacilityWork.*;
import java.security.MessageDigest;
import java.sql.Timestamp;
import java.text.Normalizer;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

public final class JdbcMerchantFacilityWork implements MerchantFacilityWork {
    private static final JsonMapper JSON=JsonMapper.builder().build();
    private final DataSource source;private final JdbcTemplate jdbc;private final BusinessShipments shipments;private final BusinessPreparationProtection hashes;private final Clock clock;private final boolean enabled;
    public JdbcMerchantFacilityWork(DataSource source,BusinessShipments shipments,BusinessPreparationProtection hashes,Clock clock,boolean enabled){this.source=source;jdbc=new JdbcTemplate(source);this.shipments=shipments;this.hashes=hashes;this.clock=clock;this.enabled=enabled;}
    private static BusinessPreparations.Failure fail(String code){return new BusinessPreparations.Failure(code);}
    private UUID org(Access a){a.requireCurrent();if(!enabled)throw fail("BUSINESS_DISABLED");if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.hasResource(source))throw new IllegalStateException("FACILITY_WORK_ADMISSION_REQUIRED");return a.scope().context().organizationId();}
    private void read(Access a,UUID site,String kind){org(a);if(site==null||!a.scope().permits("shipment.draft.read",site)||!a.scope().permits(kind.equals("PREPARATION")?"shipment.prepare":"shipment.handover.read",site))throw fail("RESOURCE_NOT_FOUND");}
    private void write(Access a,UUID site,String kind){read(a,site,kind);a.scope().requireActiveFacility(site);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT orders.merchant_work_permission(?,?,?,?)",Boolean.class,org(a),a.actorAccountId(),site,kind)))throw fail("WORK_RESPONSIBILITY_REQUIRED");}
    private BusinessShipments.Shipment shipment(Access a,UUID id){var s=shipments.get(a,id);if(s.facilityId()==null||!s.bookingState().equals("CONFIRMED")||!s.carrierState().equals("NOT_ACCEPTED"))throw fail("WORK_SOURCE_NOT_ELIGIBLE");return s;}
    private static String str(JsonNode v,String k){var n=v.get(k);return n==null||n.isNull()?null:n.asString();}
    private static UUID id(JsonNode v,String k){String n=str(v,k);return n==null?null:UUID.fromString(n);}
    private static Instant time(JsonNode v,String k){return OffsetDateTime.parse(str(v,k).replace(' ','T')).toInstant();}
    private Instant now(){return clock.instant().truncatedTo(ChronoUnit.MICROS);}
    private static String note(String n,boolean required){if(n==null){if(required)throw fail("VALIDATION_FAILED");return null;}if(n.codePoints().anyMatch(Character::isISOControl))throw fail("VALIDATION_FAILED");String v=Normalizer.normalize(n.strip(),Normalizer.Form.NFC);if(v.isEmpty()||v.codePointCount(0,v.length())>300)throw fail("VALIDATION_FAILED");return v;}
    private String raw(Access a,String kind,UUID target){var rows=jdbc.query("SELECT orders.merchant_work_snapshot(?,id)::text FROM orders."+(kind.equals("PREPARATION")?"merchant_parcel_preparation":"merchant_handover_preparation")+" WHERE organization_id=? AND id=?",(r,n)->r.getString(1),kind,org(a),target);if(rows.size()!=1)throw fail("RESOURCE_NOT_FOUND");read(a,id(JSON.readTree(rows.getFirst()),"facility_id"),kind);return rows.getFirst();}
    private static List<Check> checks(JsonNode v){List<Check> list=new ArrayList<>();for(var c:v.get("checks"))list.add(new Check(id(c,"parcel_id"),str(c,"result"),str(c,"note")));return List.copyOf(list);}
    private boolean writable(Access a,UUID site,String kind){return Boolean.TRUE.equals(jdbc.queryForObject("SELECT orders.merchant_work_permission(?,?,?,?)",Boolean.class,org(a),a.actorAccountId(),site,kind));}
    private Preparation preparation(Access a,String raw){var v=JSON.readTree(raw);var s=shipment(a,id(v,"shipment_id"));UUID site=id(v,"facility_id");read(a,site,"PREPARATION");String state=str(v,"state");List<String> actions=new ArrayList<>();if(writable(a,site,"PREPARATION")){if(state.equals("READY_TO_PACK"))actions.addAll(List.of("CHECK","PACK"));if(state.equals("PACKED"))actions.addAll(List.of("READY","REOPEN"));if(state.equals("READY_TO_HANDOVER"))actions.add("REOPEN");}return new Preparation(id(v,"id"),org(a),site,s.id(),s.code(),state,v.get("version").asLong(),v.get("cycle").asLong(),time(v,"created_at"),time(v,"updated_at"),checks(v),s.parcels(),actions);}
    @Override public Preparation get(Access a,UUID target){return preparation(a,raw(a,"PREPARATION",target));}
    @Override public WorkPage list(Access a,UUID site,String state,int page){read(a,site,"PREPARATION");if(page<0||state!=null&&!Set.of("NOT_STARTED","READY_TO_PACK","PACKED","READY_TO_HANDOVER").contains(state))throw fail("VALIDATION_FAILED");List<Object> args=new ArrayList<>(List.of(org(a),site));String where="s.organization_id=? AND s.facility_id=? AND s.owner_type='BUSINESS' AND s.booking_state='CONFIRMED' AND s.carrier_state='NOT_ACCEPTED'";if(state!=null){where+=state.equals("NOT_STARTED")?" AND w.id IS NULL":" AND w.state=?";if(!state.equals("NOT_STARTED"))args.add(state);}args.add(Math.multiplyExact((long)page,20));var ids=jdbc.query("SELECT s.id,w.id FROM orders.pilot_shipment s LEFT JOIN orders.merchant_parcel_preparation w ON w.shipment_id=s.id WHERE "+where+" ORDER BY s.created_at DESC,s.id LIMIT 21 OFFSET ?",(r,n)->new UUID[]{r.getObject(1,UUID.class),r.getObject(2,UUID.class)},args.toArray());var rows=ids.stream().limit(20).map(pair->{var s=shipment(a,pair[0]);return new WorkItem(s.id(),s.code(),s.parcels().size(),pair[1]==null?null:get(a,pair[1]));}).toList();return new WorkPage(rows,page,20,ids.size()>20);}
    record Prior(String kind,UUID target,UUID site,long expected,long result,String keyId,byte[] hash){}
    private Optional<Prior> prior(Access a,String op,UUID key){return jdbc.query("SELECT resource_kind,target_id,facility_id,expected_version,result_version,fingerprint_key_id,fingerprint FROM orders.merchant_facility_work_receipt WHERE organization_id=? AND actor_account_id=? AND operation=? AND operation_key=?",(r,n)->new Prior(r.getString(1),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getLong(4),r.getLong(5),r.getString(6),r.getBytes(7)),org(a),a.actorAccountId(),op,key).stream().findFirst();}
    private byte[] hash(Access a,String keyId,String op,UUID target,long expected,Object payload){return hashes.hash(keyId,"merchant-facility-work-v1",org(a),a.actorAccountId(),op,target,expected,JSON.writeValueAsString(payload));}
    private String replay(Access a,String op,UUID target,long expected,Object payload,Prior p){raw(a,p.kind(),p.target());write(a,p.site(),p.kind());byte[] h=hash(a,p.keyId(),op,target,expected,payload);try{if(!p.target().equals(target)||p.expected()!=expected||!MessageDigest.isEqual(h,p.hash()))throw fail("IDEMPOTENCY_CONFLICT");}finally{Arrays.fill(h,(byte)0);Arrays.fill(p.hash(),(byte)0);}return jdbc.queryForObject("SELECT snapshot::text FROM orders.merchant_facility_work_event WHERE resource_kind=? AND target_id=? AND version=?",String.class,p.kind(),target,p.result());}
    private void evidence(Access a,String kind,UUID target,UUID site,long expected,String action,UUID key,Object payload,UUID parcel,String reason,Instant stamp){String op=kind+"_"+action;String raw=raw(a,kind,target);jdbc.update("INSERT INTO orders.merchant_facility_work_event VALUES(?,?,?,?,?,?,?,?,?,?,?::jsonb,?,?)",kind,target,org(a),site,expected+1,a.actorAccountId(),op,key,parcel,reason,raw,a.requestId(),Timestamp.from(stamp));String kid=hashes.active();byte[] h=hash(a,kid,op,target,expected,payload);try{jdbc.update("INSERT INTO orders.merchant_facility_work_receipt VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",org(a),a.actorAccountId(),op,key,kind,target,site,expected,expected+1,kid,h,Timestamp.from(stamp));}finally{Arrays.fill(h,(byte)0);}a.meaningfulAction();a.requireCurrent();}
    @Override public Preparation create(Access a,UUID shipmentId,UUID key){var s=shipment(a,shipmentId);write(a,s.facilityId(),"PREPARATION");var p=prior(a,"PREPARATION_CREATE",key);if(p.isPresent())return preparation(a,replay(a,"PREPARATION_CREATE",p.get().target(),0,shipmentId,p.get()));if(jdbc.queryForObject("SELECT count(*) FROM orders.merchant_parcel_preparation WHERE shipment_id=?",Integer.class,shipmentId)!=0)throw fail("WORK_ALREADY_STARTED");UUID target=UUID.randomUUID();Instant stamp=now();jdbc.update("INSERT INTO orders.merchant_parcel_preparation VALUES(?,?,?,?,'READY_TO_PACK',1,1,orders.merchant_parcel_fingerprint(?),?,?)",target,org(a),s.facilityId(),s.id(),s.id(),Timestamp.from(stamp),Timestamp.from(stamp));evidence(a,"PREPARATION",target,s.facilityId(),0,"CREATE",key,shipmentId,null,null,stamp);return get(a,target);}
    private Check valid(Check c,boolean batch){if(c==null||c.parcelId()==null||c.result()==null||!(batch?Set.of("PRESENT","MISSING","VERIFY"):Set.of("OK","VERIFY")).contains(c.result()))throw fail("VALIDATION_FAILED");return new Check(c.parcelId(),c.result(),note(c.note(),false));}
    private void version(long actual,long expected){if(actual!=expected)throw fail("PRECONDITION_STALE");}
    @Override public Preparation check(Access a,UUID target,Check input,long expected,UUID key){var c=valid(input,false);var before=get(a,target);write(a,before.facilityId(),"PREPARATION");var old=prior(a,"PREPARATION_CHECK",key);if(old.isPresent())return preparation(a,replay(a,"PREPARATION_CHECK",target,expected,c,old.get()));version(before.version(),expected);if(!before.state().equals("READY_TO_PACK")||before.parcels().stream().noneMatch(p->p.id().equals(c.parcelId())))throw fail("WORK_PARCEL_NOT_ELIGIBLE");Instant stamp=now();jdbc.update("UPDATE orders.merchant_parcel_preparation SET version=version+1,updated_at=? WHERE id=? AND version=?",Timestamp.from(stamp),target,expected);jdbc.update("INSERT INTO orders.merchant_preparation_check VALUES(?,?,?,?,?,?) ON CONFLICT(preparation_id,parcel_id) DO UPDATE SET result=excluded.result,note=excluded.note,cycle=excluded.cycle",target,before.shipmentId(),c.parcelId(),c.result(),c.note(),before.cycle());evidence(a,"PREPARATION",target,before.facilityId(),expected,"CHECK",key,c,c.parcelId(),null,stamp);return get(a,target);}
    private boolean allChecked(List<PilotShipments.Parcel> parcels,List<Check> checks,String result){return !parcels.isEmpty()&&parcels.stream().allMatch(p->checks.stream().anyMatch(c->c.parcelId().equals(p.id())&&c.result().equals(result)));}
    @Override public Preparation transition(Access a,UUID target,String action,String suppliedReason,long expected,UUID key){if(action==null||!Set.of("PACK","READY","REOPEN").contains(action))throw fail("VALIDATION_FAILED");String reason=note(suppliedReason,action.equals("REOPEN"));var before=get(a,target);write(a,before.facilityId(),"PREPARATION");var payload=Arrays.asList(action,reason);var old=prior(a,"PREPARATION_"+action,key);if(old.isPresent())return preparation(a,replay(a,"PREPARATION_"+action,target,expected,payload,old.get()));version(before.version(),expected);if(!before.allowedActions().contains(action))throw fail("WORK_STATE_CONFLICT");if(!action.equals("REOPEN")&&!allChecked(before.parcels(),before.checks(),"OK"))throw fail("WORK_PARCELS_INCOMPLETE");if(action.equals("REOPEN")&&jdbc.queryForObject("SELECT count(*) FROM orders.merchant_handover_shipment i JOIN orders.merchant_handover_preparation b ON b.id=i.batch_id WHERE i.shipment_id=? AND i.active AND b.state='READY'",Integer.class,before.shipmentId())>0)throw fail("HANDOVER_REOPEN_REQUIRED");Instant stamp=now();jdbc.update("UPDATE orders.merchant_parcel_preparation SET state=?,version=version+1,cycle=cycle+?,updated_at=? WHERE id=? AND version=?",action.equals("PACK")?"PACKED":action.equals("READY")?"READY_TO_HANDOVER":"READY_TO_PACK",action.equals("REOPEN")?1:0,Timestamp.from(stamp),target,expected);if(action.equals("REOPEN"))jdbc.update("DELETE FROM orders.merchant_preparation_check WHERE preparation_id=?",target);evidence(a,"PREPARATION",target,before.facilityId(),expected,action,key,payload,null,reason,stamp);return get(a,target);}
    private Batch batchView(Access a,String raw,long version){var v=JSON.readTree(raw);UUID site=id(v,"facility_id"),target=id(v,"id");read(a,site,"HANDOVER");var members=new ArrayList<BatchShipment>();for(var item:v.get("items")){var s=shipment(a,id(item,"shipment_id"));if(!s.facilityId().equals(site))throw fail("WORK_SOURCE_NOT_ELIGIBLE");members.add(new BatchShipment(s.id(),s.code(),s.parcels()));}var history=jdbc.query("SELECT operation,actor_account_id,reason,occurred_at FROM orders.merchant_facility_work_event WHERE resource_kind='HANDOVER' AND target_id=? AND version<=? ORDER BY version LIMIT 1001",(r,n)->new Event(r.getString(1),r.getObject(2,UUID.class),r.getString(3),r.getTimestamp(4).toInstant()),target,version);if(history.size()>1000)throw fail("WORK_HISTORY_LIMIT_EXCEEDED");List<String> actions=new ArrayList<>();String state=str(v,"state");if(!state.equals("CANCELLED")&&writable(a,site,"HANDOVER")){actions.addAll(List.of("ITEMS","CANCEL"));if(state.equals("DRAFT"))actions.addAll(List.of("CHECK","READY"));if(state.equals("READY"))actions.add("REOPEN");}return new Batch(target,org(a),site,state,version,v.get("cycle").asLong(),time(v,"created_at"),time(v,"updated_at"),members,checks(v),history,actions);}
    @Override public Batch batch(Access a,UUID target){String raw=raw(a,"HANDOVER",target);return batchView(a,raw,JSON.readTree(raw).get("version").asLong());}
    @Override public BatchPage batches(Access a,UUID site,String state,int page){org(a);if(page<0||state!=null&&!Set.of("DRAFT","READY","CANCELLED").contains(state))throw fail("VALIDATION_FAILED");List<Object> args=new ArrayList<>();args.add(org(a));String where="organization_id=?";if(site!=null){read(a,site,"HANDOVER");where+=" AND facility_id=?";args.add(site);}else if(!a.scope().permits("shipment.draft.read",null)||!a.scope().permits("shipment.handover.read",null)){var sites=new HashSet<>(a.scope().facilities("shipment.handover.read"));sites.addAll(a.scope().facilities("shipment.draft.read"));sites.removeIf(s->!a.scope().permits("shipment.draft.read",s)||!a.scope().permits("shipment.handover.read",s));if(sites.isEmpty())throw fail("RESOURCE_NOT_FOUND");where+=" AND facility_id IN ("+String.join(",",Collections.nCopies(sites.size(),"?"))+")";args.addAll(sites);}if(state!=null){where+=" AND state=?";args.add(state);}args.add(Math.multiplyExact((long)page,20));var ids=jdbc.query("SELECT id FROM orders.merchant_handover_preparation WHERE "+where+" ORDER BY updated_at DESC,id LIMIT 21 OFFSET ?",(r,n)->r.getObject(1,UUID.class),args.toArray());return new BatchPage(ids.stream().limit(20).map(i->batch(a,i)).toList(),page,20,ids.size()>20);}
    private List<UUID> selected(Access a,UUID site,List<UUID> ids,UUID current){if(ids==null||ids.isEmpty()||ids.size()>20||ids.stream().anyMatch(Objects::isNull)||new HashSet<>(ids).size()!=ids.size())throw fail("VALIDATION_FAILED");var result=ids.stream().sorted(Comparator.comparing(UUID::toString)).toList();int total=0;for(UUID id:result){var s=shipment(a,id);if(!site.equals(s.facilityId()))throw fail("WORK_SOURCE_NOT_ELIGIBLE");total+=s.parcels().size();if(jdbc.queryForObject("SELECT count(*) FROM orders.merchant_handover_shipment WHERE shipment_id=? AND active AND batch_id<>?",Integer.class,id,current)==1)throw fail("WORK_ALREADY_IN_HANDOVER");}if(total>100)throw fail("WORK_BATCH_LIMIT_EXCEEDED");return result;}
    private void bind(Access a,UUID target,UUID site,List<UUID> ids){for(UUID s:ids)jdbc.update("INSERT INTO orders.merchant_handover_shipment VALUES(?,?,?,?,TRUE)",target,org(a),site,s);}
    @Override public Batch createBatch(Access a,UUID site,List<UUID> supplied,UUID key){write(a,site,"HANDOVER");var old=prior(a,"HANDOVER_CREATE",key);UUID target=old.map(Prior::target).orElseGet(UUID::randomUUID);var ids=selected(a,site,supplied,target);var payload=List.of(site,ids);if(old.isPresent())return batchView(a,replay(a,"HANDOVER_CREATE",target,0,payload,old.get()),old.get().result());Instant stamp=now();jdbc.update("INSERT INTO orders.merchant_handover_preparation VALUES(?,?,?,'DRAFT',1,1,?,?)",target,org(a),site,Timestamp.from(stamp),Timestamp.from(stamp));bind(a,target,site,ids);evidence(a,"HANDOVER",target,site,0,"CREATE",key,payload,null,null,stamp);return batch(a,target);}
    @Override public Batch items(Access a,UUID target,List<UUID> supplied,long expected,UUID key){var before=batch(a,target);write(a,before.facilityId(),"HANDOVER");var ids=selected(a,before.facilityId(),supplied,target);var old=prior(a,"HANDOVER_ITEMS",key);if(old.isPresent())return batchView(a,replay(a,"HANDOVER_ITEMS",target,expected,ids,old.get()),old.get().result());version(before.version(),expected);if(before.state().equals("CANCELLED"))throw fail("WORK_STATE_CONFLICT");Instant stamp=now();jdbc.update("UPDATE orders.merchant_handover_preparation SET state='DRAFT',version=version+1,cycle=cycle+1,updated_at=? WHERE id=? AND version=?",Timestamp.from(stamp),target,expected);jdbc.update("DELETE FROM orders.merchant_handover_check WHERE batch_id=?",target);jdbc.update("DELETE FROM orders.merchant_handover_shipment WHERE batch_id=?",target);bind(a,target,before.facilityId(),ids);evidence(a,"HANDOVER",target,before.facilityId(),expected,"ITEMS",key,ids,null,null,stamp);return batch(a,target);}
    @Override public Batch checkBatch(Access a,UUID target,Check supplied,long expected,UUID key){var c=valid(supplied,true);var before=batch(a,target);write(a,before.facilityId(),"HANDOVER");var old=prior(a,"HANDOVER_CHECK",key);if(old.isPresent())return batchView(a,replay(a,"HANDOVER_CHECK",target,expected,c,old.get()),old.get().result());version(before.version(),expected);if(!before.state().equals("DRAFT"))throw fail("WORK_STATE_CONFLICT");var s=before.shipments().stream().filter(i->i.parcels().stream().anyMatch(p->p.id().equals(c.parcelId()))).findFirst().orElseThrow(()->fail("WORK_PARCEL_NOT_ELIGIBLE"));Instant stamp=now();jdbc.update("UPDATE orders.merchant_handover_preparation SET version=version+1,updated_at=? WHERE id=? AND version=?",Timestamp.from(stamp),target,expected);jdbc.update("INSERT INTO orders.merchant_handover_check VALUES(?,?,?,?,?,?) ON CONFLICT(batch_id,parcel_id) DO UPDATE SET result=excluded.result,note=excluded.note,cycle=excluded.cycle",target,s.shipmentId(),c.parcelId(),c.result(),c.note(),before.cycle());evidence(a,"HANDOVER",target,before.facilityId(),expected,"CHECK",key,c,c.parcelId(),null,stamp);return batch(a,target);}
    @Override public Batch transitionBatch(Access a,UUID target,String action,String suppliedReason,long expected,UUID key){if(action==null||!Set.of("READY","REOPEN","CANCEL").contains(action))throw fail("VALIDATION_FAILED");String reason=note(suppliedReason,!action.equals("READY"));var before=batch(a,target);write(a,before.facilityId(),"HANDOVER");var payload=Arrays.asList(action,reason);var old=prior(a,"HANDOVER_"+action,key);if(old.isPresent())return batchView(a,replay(a,"HANDOVER_"+action,target,expected,payload,old.get()),old.get().result());version(before.version(),expected);if(!before.allowedActions().contains(action))throw fail("WORK_STATE_CONFLICT");if(action.equals("READY")){for(var s:before.shipments()){if(!allChecked(s.parcels(),before.checks(),"PRESENT")||jdbc.queryForObject("SELECT count(*) FROM orders.merchant_parcel_preparation WHERE shipment_id=? AND state='READY_TO_HANDOVER' AND source_fingerprint=orders.merchant_parcel_fingerprint(?)",Integer.class,s.shipmentId(),s.shipmentId())!=1)throw fail("WORK_PARCELS_INCOMPLETE");}}Instant stamp=now();jdbc.update("UPDATE orders.merchant_handover_preparation SET state=?,version=version+1,cycle=cycle+?,updated_at=? WHERE id=? AND version=?",action.equals("READY")?"READY":action.equals("REOPEN")?"DRAFT":"CANCELLED",action.equals("REOPEN")?1:0,Timestamp.from(stamp),target,expected);if(action.equals("REOPEN"))jdbc.update("DELETE FROM orders.merchant_handover_check WHERE batch_id=?",target);if(action.equals("CANCEL"))jdbc.update("UPDATE orders.merchant_handover_shipment SET active=FALSE WHERE batch_id=?",target);evidence(a,"HANDOVER",target,before.facilityId(),expected,action,key,payload,null,reason,stamp);return batch(a,target);}
    @Override public byte[] document(Access a,UUID target){return new MerchantHandoverRenderer().render(batch(a,target));}
    @Override public Receipt receipt(Access a,String op,UUID key){if(op==null||!Set.of("PREPARATION_CREATE","PREPARATION_CHECK","PREPARATION_PACK","PREPARATION_READY","PREPARATION_REOPEN","HANDOVER_CREATE","HANDOVER_ITEMS","HANDOVER_CHECK","HANDOVER_READY","HANDOVER_REOPEN","HANDOVER_CANCEL").contains(op))throw fail("RESOURCE_NOT_FOUND");var p=prior(a,op,key).orElseThrow(()->fail("RESOURCE_NOT_FOUND"));raw(a,p.kind(),p.target());write(a,p.site(),p.kind());return new Receipt(op,p.target(),"COMMITTED",p.result());}
}
